    <style>
        *{box-sizing:border-box}body{margin:0;background:#f3f7f5;color:#17251f;font-family:Inter,ui-sans-serif,system-ui,-apple-system,sans-serif}.wrap{max-width:980px;margin:0 auto;padding:28px 18px 70px}.hero{background:linear-gradient(125deg,#123f35,#18765a);border-radius:22px;padding:27px;color:#fff;box-shadow:0 15px 35px #123d3028}.eyebrow{font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:#b7ead7}.hero h1{margin:6px 0 5px;font-size:28px}.hero p{margin:0;color:#d6eee5}.fixed{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:20px}.fixed div{background:#ffffff16;border:1px solid #ffffff2c;border-radius:12px;padding:11px}.fixed span{display:block;font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:#b7d6cb}.fixed b{display:block;margin-top:3px;font-size:14px}.card{background:#fff;border:1px solid #dbe7e2;border-radius:18px;padding:22px;margin-top:16px;box-shadow:0 5px 18px #173d3010}.card h2{font-size:18px;margin:0 0 4px}.hint{font-size:12px;color:#6d7d76;margin:0 0 18px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.grid.four{grid-template-columns:repeat(4,1fr)}label{font-size:12px;font-weight:750;color:#4f625a;display:block}input,textarea{width:100%;border:1px solid #cddbd5;border-radius:10px;padding:11px 12px;margin-top:5px;background:#fff;color:#17251f;font:inherit}input:focus,textarea:focus{outline:2px solid #62b99a55;border-color:#298365}.person,.vehicle,.pet,.extra{background:#f6f9f8;border:1px solid #dfe9e5;border-radius:14px;padding:16px;margin-top:12px}.row-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.row-head b{font-size:14px}.remove{border:0;background:#feecec;color:#a52e2e;border-radius:8px;padding:6px 9px;cursor:pointer}.add{border:1px dashed #53a889;background:#eff9f5;color:#176b53;border-radius:10px;padding:10px 14px;font-weight:750;cursor:pointer;margin-top:12px}.docs{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-top:13px}.doc{background:#fff;border:1px solid #dfebe6;border-radius:10px;padding:10px}.doc b{font-size:11px}.checks{display:flex;gap:18px;flex-wrap:wrap;margin-top:13px}.checks label{display:flex;align-items:center;gap:7px}.checks input{width:auto;margin:0}.submit{width:100%;border:0;background:#176b53;color:#fff;border-radius:12px;padding:14px;font-size:15px;font-weight:800;cursor:pointer;margin-top:17px}.errors{background:#fff0f0;color:#992e2e;border:1px solid #f3caca;border-radius:14px;padding:14px 18px;margin-top:16px}.state{text-align:center;background:#fff;border-radius:20px;padding:50px 25px;margin-top:18px;border:1px solid #dbe7e2}.state .icon{font-size:42px}.state h2{margin:10px}.terms{display:flex;align-items:flex-start;gap:10px;margin-top:16px}.terms input{width:auto;margin-top:3px}.terms a{color:#176b53}@media(max-width:700px){.fixed,.grid.four{grid-template-columns:repeat(2,1fr)}.grid,.docs{grid-template-columns:1fr}.hero h1{font-size:23px}}
    </style>
