            <section class="card"><h2>Fecha y horario</h2><p class="hint">Indique el período durante el cual se permitirá el ingreso.</p><div class="grid four">
                <label>Fecha desde<input type="date" name="start_date" min="{{ now()->format('Y-m-d') }}" value="{{ old('start_date') }}" required></label><label>Hora desde<input type="time" name="start_time" value="{{ old('start_time') }}" required></label>
                <label>Fecha hasta<input type="date" name="end_date" min="{{ now()->format('Y-m-d') }}" value="{{ old('end_date') }}" required></label><label>Hora hasta<input type="time" name="end_time" value="{{ old('end_time') }}" required></label>
            </div></section>
