            <section class="card"><h2>Vehículos</h2><p class="hint">Opcional. Si agrega un vehículo, complete todos sus datos.</p><div id="vehicles"></div><button class="add" type="button" onclick="addVehicle()">+ Agregar vehículo</button></section>
            <section class="card"><h2>Información adicional</h2><div id="extras"></div><button class="add" type="button" onclick="addExtra()">+ Agregar documento</button><div id="pets"></div><button class="add" type="button" onclick="addPet()">+ Agregar mascota</button><label style="margin-top:16px">Observaciones<textarea name="observations" rows="4">{{ old('observations') }}</textarea></label></section>
            <section class="card"><label class="terms"><input type="checkbox" name="accept_terms" value="1" required><span>He leído y acepto los <a href="{{ route('terminos-y-condiciones',['id'=>1]) }}" target="_blank">términos y condiciones</a>.</span></label><button class="submit" type="submit">Enviar al propietario para aprobación</button></section>
        </form>
        <template id="person-template"><div class="person"><div class="row-head"><b>Persona</b><button type="button" class="remove" onclick="removeRow(this)">Quitar</button></div><div class="grid four"><label>DNI<input name="people[__I__][dni]" inputmode="numeric" required></label><label>Nombre<input name="people[__I__][first_name]" required></label><label>Apellido<input name="people[__I__][last_name]" required></label><label>Teléfono<input name="people[__I__][phone]" inputmode="numeric" maxlength="15"></label></div><div class="checks"><label><input type="checkbox" name="people[__I__][is_responsable]" value="1"> Responsable</label><label><input type="checkbox" name="people[__I__][is_acompanante]" value="1"> Acompañante</label><label><input type="checkbox" name="people[__I__][is_menor]" value="1"> Menor</label></div><div class="docs">@foreach($personDocuments as $j=>$doc)<div class="doc"><b>{{ $doc['name'] }}{{ $doc['required']?' *':'' }}</b><input type="hidden" name="people[__I__][documents][{{ $j }}][name]" value="{{ $doc['name'] }}"><input type="file" name="people[__I__][documents][{{ $j }}][file]" accept="image/*,.pdf" {{ $doc['required']?'required':'' }}>@if($doc['date_required'])<label>Vencimiento<input type="date" name="people[__I__][documents][{{ $j }}][expires_at]" required></label>@endif</div>@endforeach</div></div></template>
        <template id="vehicle-template"><div class="vehicle"><div class="row-head"><b>Vehículo</b><button type="button" class="remove" onclick="removeRow(this)">Quitar</button></div><div class="grid four"><label>Marca<input name="vehicles[__I__][marca]" required></label><label>Modelo<input name="vehicles[__I__][modelo]" required></label><label>Patente<input name="vehicles[__I__][patente]" required></label><label>Color<input name="vehicles[__I__][color]" required></label></div><div class="docs">@foreach($vehicleDocuments as $j=>$doc)<div class="doc"><b>{{ $doc['name'] }}{{ $doc['required']?' *':'' }}</b><input type="hidden" name="vehicles[__I__][documents][{{ $j }}][name]" value="{{ $doc['name'] }}"><input type="file" name="vehicles[__I__][documents][{{ $j }}][file]" accept="image/*,.pdf" {{ $doc['required']?'required':'' }}>@if($doc['date_required'])<label>Vencimiento<input type="date" name="vehicles[__I__][documents][{{ $j }}][expires_at]" required></label>@endif</div>@endforeach</div></div></template>
        <template id="extra-template"><div class="extra"><div class="row-head"><b>Documento adicional</b><button type="button" class="remove" onclick="removeRow(this)">Quitar</button></div><div class="grid"><label>Descripción<input name="extra_documents[__I__][description]"></label><label>Archivo<input type="file" name="extra_documents[__I__][file]" accept="image/*,.pdf" required></label></div></div></template>
        <template id="pet-template"><div class="pet"><div class="row-head"><b>Mascota</b><button type="button" class="remove" onclick="removeRow(this)">Quitar</button></div><div class="grid four"><label>Tipo<input name="pets[__I__][type]"></label><label>Raza<input name="pets[__I__][breed]"></label><label>Nombre<input name="pets[__I__][name]"></label><label class="terms"><input type="checkbox" name="pets[__I__][vaccinated]" value="1"> Vacunada</label></div></div></template>
        <script>
            let counters={person:0,vehicle:0,extra:0,pet:0};
            function oldValue(data,name){const keys=[...name.matchAll(/\[([^\]]+)\]/g)].map(match=>match[1]).slice(1);let value=data;for(const key of keys){if(value===undefined||value===null)return undefined;value=value[key]}return value}
            function add(kind,target,data={}){const i=counters[kind]++;const container=document.getElementById(target);container.insertAdjacentHTML('beforeend',document.getElementById(kind+'-template').innerHTML.replaceAll('__I__',i));const row=container.lastElementChild;row.querySelectorAll('input,textarea').forEach(field=>{if(field.type==='file')return;const value=oldValue(data,field.name);if(value===undefined)return;if(field.type==='checkbox')field.checked=Boolean(value);else field.value=value});}
            function addPerson(data={}){add('person','people',data)}function addVehicle(data={}){add('vehicle','vehicles',data)}function addExtra(data={}){add('extra','extras',data)}function addPet(data={}){add('pet','pets',data)}function removeRow(button){button.closest('.person,.vehicle,.extra,.pet').remove()}
            const previous={people:@json(old('people',[])),vehicles:@json(old('vehicles',[])),extras:@json(old('extra_documents',[])),pets:@json(old('pets',[]))};
            previous.people.length?previous.people.forEach(addPerson):addPerson();previous.vehicles.forEach(addVehicle);previous.extras.forEach(addExtra);previous.pets.forEach(addPet);
        </script>
    @endif
</main></body></html>
